#!/usr/bin/env python3
"""Builds Playgrounds/MobileBanking.swiftpm, a copy of the app that opens in Swift Playgrounds on iPad.

The Xcode project in MobileBanking/ stays the main project. Run this script after every change
of the app code (CI checks that the copy is up to date):

    python3 scripts/make_playground.py
"""
import json
import pathlib
import shutil

ROOT = pathlib.Path(__file__).resolve().parent.parent
SOURCE = ROOT / "MobileBanking"
PACKAGE = ROOT / "Playgrounds" / "MobileBanking.swiftpm"
APP = PACKAGE / "App"

# Info.plist is generated by Xcode for the Xcode project only. Swift Playgrounds cannot compile
# String Catalogs (.xcstrings), so the texts are converted to classic .lproj/Localizable.strings.
SKIP = {"Info.plist", "InfoPlist.xcstrings", "Localizable.xcstrings"}

PACKAGE_SWIFT = """// swift-tools-version: 5.9
// GENERATED by scripts/make_playground.py from the MobileBanking/ folder. Do not edit by hand.

import PackageDescription
import AppleProductTypes

let package = Package(
    name: "MobileBanking",
    defaultLocalization: "cs",
    platforms: [
        .iOS("17.0")
    ],
    products: [
        .iOSApplication(
            name: "MobileBanking",
            targets: ["AppModule"],
            bundleIdentifier: "cz.mobiletech.MobileBanking.playground",
            displayVersion: "1.0",
            bundleVersion: "1",
            appIcon: .asset("AppIcon"),
            accentColor: .presetColor(.indigo),
            supportedDeviceFamilies: [
                .pad,
                .phone
            ],
            supportedInterfaceOrientations: [
                .portrait,
                .landscapeRight,
                .landscapeLeft,
                .portraitUpsideDown(.when(deviceFamilies: [.pad]))
            ],
            additionalInfoPlistContentFilePath: "AdditionalInfo.plist"
        )
    ],
    targets: [
        .executableTarget(
            name: "AppModule",
            path: "App",
            resources: [
                .process("Resources")
            ]
        )
    ]
)
"""

ADDITIONAL_INFO = """<?xml version="1.0" encoding="UTF-8"?>
<!DOCTYPE plist PUBLIC "-//Apple//DTD PLIST 1.0//EN" "http://www.apple.com/DTDs/PropertyList-1.0.dtd">
<plist version="1.0">
<dict>
	<key>NSFaceIDUsageDescription</key>
	<string>Face ID slouží k rychlému a bezpečnému odemknutí aplikace.</string>
	<key>CFBundleDevelopmentRegion</key>
	<string>cs</string>
	<key>CFBundleLocalizations</key>
	<array>
		<string>cs</string>
		<string>en</string>
	</array>
</dict>
</plist>
"""


def strings_escape(text: str) -> str:
    return text.replace("\\", "\\\\").replace('"', '\\"').replace("\n", "\\n")


def write_strings_files() -> None:
    catalog = json.loads((SOURCE / "Resources" / "Localizable.xcstrings").read_text(encoding="utf-8"))
    languages = {"cs": [], "en": []}
    for key, entry in sorted(catalog["strings"].items()):
        for language, lines in languages.items():
            unit = entry.get("localizations", {}).get(language, {}).get("stringUnit")
            if unit:
                lines.append(f'"{strings_escape(key)}" = "{strings_escape(unit["value"])}";')
    for language, lines in languages.items():
        folder = APP / "Resources" / f"{language}.lproj"
        folder.mkdir(parents=True, exist_ok=True)
        header = "/* GENERATED by scripts/make_playground.py from Localizable.xcstrings. Do not edit. */\n"
        (folder / "Localizable.strings").write_text(header + "\n".join(lines) + "\n", encoding="utf-8")


def main() -> None:
    if PACKAGE.exists():
        shutil.rmtree(PACKAGE)
    shutil.copytree(SOURCE, APP, ignore=lambda _dir, names: [n for n in names if n in SKIP or n == ".DS_Store"])
    write_strings_files()
    (PACKAGE / "Package.swift").write_text(PACKAGE_SWIFT, encoding="utf-8")
    (PACKAGE / "AdditionalInfo.plist").write_text(ADDITIONAL_INFO, encoding="utf-8")
    print(f"Created {PACKAGE.relative_to(ROOT)}")


if __name__ == "__main__":
    main()
